CREATE TABLE IF NOT EXISTS public.promise_to_pay (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, installment_id uuid REFERENCES public.installments(id) ON DELETE SET NULL, sale_id uuid REFERENCES public.sales(id) ON DELETE SET NULL, driver_id uuid REFERENCES public.drivers(id) ON DELETE SET NULL, promised_date date NOT NULL, promised_amount numeric NOT NULL CHECK (promised_amount > 0), status text NOT NULL DEFAULT 'OPEN', notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);